#ifndef HTML_H
#define HTML_H

const char * indexHtml = "<html lang=\"en\"><head> <meta charset=\"UTF-8\"> <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"> <title>Water Guy</title> <style> body{ display:flex; justify-content:center; align-items:flex-start; min-height:100vh; margin:0; padding:20px 0; font-family:Arial,sans-serif; background-color:#f0f0f0; } .wrapper{ text-align:center; background:#fff; padding:20px; border-radius:8px; box-shadow:0 4px 8px rgba(0,0,0,0.1); max-width:400px; width:90%; } .form-signin{ display:flex; flex-direction:column; align-items:center; } .form-signin-heading{ margin-bottom:20px; font-size:1.5rem; color:#333; } .form-control{ width:100%; height:50px; padding:10px; margin-bottom:15px; font-size:1rem; border:1px solid #ccc; border-radius:4px; box-sizing:border-box; } textarea.form-control{ height:300px; resize:none; overflow-wrap:break-word; font-family:monospace; } .btn{ width:100%; height:50px; font-size:1rem; background-color:#007bff; color:#fff; border:none; border-radius:4px; cursor:pointer; margin-bottom:10px; } .btn:hover{ background-color:#0056b3; } .divider{ width:100%; height:1px; background:#ddd; margin:20px 0; } #toggleResult{ font-size:0.9rem; color:#333; margin-top:5px; } </style></head><body> <div class=\"wrapper\"> <!-- Wi-Fi config --> <form class=\"form-signin\" method=\"POST\" action=\"/\"> <h2 class=\"form-signin-heading\">~Water Guy Wi-Fi~</h2> <input type=\"text\" class=\"form-control\" name=\"ssid\" placeholder=\"SSID\" required autofocus> <input type=\"password\" class=\"form-control\" name=\"password\" placeholder=\"Password\" required> <button class=\"btn\" type=\"submit\">Save Wi-Fi</button> </form> <div class=\"divider\"></div> <!-- Manual pin toggle --> <h3>Manual Pin Toggle</h3> <select class=\"form-control\" id=\"pinSelect\"> <option value=\"\" disabled selected>Select GPIO</option> <option value=\"2\">GPIO 2</option> <option value=\"4\">GPIO 4</option> <option value=\"5\">GPIO 5</option> <option value=\"12\">GPIO 12</option> <option value=\"13\">GPIO 13</option> <option value=\"14\">GPIO 14</option> <option value=\"16\">GPIO 16</option> </select> <button class=\"btn\" onclick=\"togglePin()\">Toggle Pin</button> <p id=\"toggleResult\"></p> <div class=\"divider\"></div> <!-- Irrigation config --> <form class=\"form-signin\" method=\"POST\" action=\"/saveConfig\"> <h3>Irrigation Config</h3> <textarea class=\"form-control\" name=\"config\">{{FILE_CONTENT}}</textarea> <button class=\"btn\" type=\"submit\">Save Config</button> </form> </div> <script> function togglePin() { const select = document.getElementById(\"pinSelect\"); const result = document.getElementById(\"toggleResult\"); const pin = select.value; result.innerText = \"\"; if (!pin) { result.innerText = \"Please select a GPIO\"; return; } fetch(`/toggle?pin=${pin}`) .then(res => res.text()) .then(txt => { result.innerText = txt; }) .catch(() => { result.innerText = \"Error toggling pin\"; }); } </script></body></html>";

#endif // HTML_H
